SELECT COUNT(*)
FROM users
WHERE username = #{username}

SELECT COUNT(*)
FROM users
WHERE phone = #{phone}

mapper.update:
UPDATE users
SET last_login_at = NOW()
WHERE id = #{id}

UPDATE user_profiles
SET nickname = COALESCE(#{nickname}, nickname),
    signature = COALESCE(#{signature}, signature),
    gender = #{gender},
    birthday = #{birthday}
WHERE user_id = #{userId}

UPDATE user_profiles
SET avatar_url = #{avatar}
WHERE user_id = #{userId}
